// Pre-rendered large continuous reverb for the final two-shaku trial only.
// Parallel combs + all-pass diffusion, damped stereo tail; no runtime convolution.
const samples={"Shoot_B_05":{"rate":24000,"channels":2,"length":255834,"scale":1.151144038082717,"data":""},"Shoot_B_06":{"rate":24000,"channels":2,"length":251464,"scale":1.1511872789283322,"data":""}};
export function twoShakuCodaBuffer(context,key){const s=samples[key];if(!s)return null;const raw=Uint8Array.from(atob(s.data),c=>c.charCodeAt(0)),v=new DataView(raw.buffer),b=context.createBuffer(2,s.length,s.rate);for(let c=0;c<2;c++){const d=b.getChannelData(c);for(let i=0;i<s.length;i++)d[i]=v.getInt16((i*2+c)*2,true)/32767*s.scale;}return b;}
